parameters.jsCode:
const jwtData = $input.first().json || {};
const token = jwtData.token || '';

const empRow = $('Postgres - Authenticate via pgcrypto crypt()').first().json;

return [{
  json: {
    success: true,
    statusCode: 200,
    token: token,
    role: empRow.role || 'EMPLOYEE',
    employee: {
      id: empRow.id,
      firstName: empRow.first_name,
      lastName: empRow.last_name,
      email: empRow.email,
      phone: empRow.phone,
      avatarUrl: empRow.avatar_url || null,
      designation: empRow.designation,
      joiningDate: typeof empRow.joining_date === 'string' ? empRow.joining_date.split('T')[0] : empRow.joining_date,
      employmentType: empRow.employment_type || 'Full-time',
      workLocation: empRow.work_location || 'Chinar Park, Teghoria, Kolkata (In-Office)',
      role: empRow.role || 'EMPLOYEE'
    }
  }
}];

